                         0, 0, 0, 0, 10, 20, 30, 20, 10, 0,
                         ...Array(374).fill(0)
                       ],
                       [1, 384]),
                   tf.tensor2d(
                       [
                         0, 0, 0, 0, 10, 20, 30, 20, 10, 20,
                         ...Array(374).fill(0)
                       ],
                       [1, 384])]);
      return Promise.resolve(model);
    });
  })

