beforeAll(() => {
  serverState = {
    waitForResultAttempts: 0,
    retryOnErrorAttempts: 0,
    mixedAttempts: 0,
    tokenRequests: 0,
  }

  app = express()

  app.get('/api/query/read-model/resolver', (req: any, res: any) => {
    res.setHeader('Date', '12345')
    res.send(
      JSON.stringify({
        data: {
          status: 'valid',
        },
      })
    )
  })

  app.get('/api/query/read-model/wait-for-result', (req: any, res: any) => {
    serverState.waitForResultAttempts++
    res.setHeader('Date', '12345')
    if (serverState.waitForResultAttempts > 3) {
      res.send(
        JSON.stringify({
          data: {
            valid: true,
          },
        })
      )
    } else {
      res.send(
        JSON.stringify({
          data: {
            valid: false,
          },
        })
      )
    }
  })

  app.get('/api/query/read-model/retry-on-error', (req: any, res: any) => {
    serverState.retryOnErrorAttempts++
    res.setHeader('Date', '12345')
    if (serverState.retryOnErrorAttempts > 3) {
      res.send(
        JSON.stringify({
          data: {
            valid: true,
          },
        })
      )
    } else {
      res.status(500 + serverState.retryOnErrorAttempts)
      res.send(
        JSON.stringify({
          message: 'error',
        })
      )
    }
  })

  app.get('/api/query/read-model/mixed-middleware', (req: any, res: any) => {
    serverState.mixedAttempts++
    const { mixedAttempts } = serverState
    res.setHeader('Date', '12345')

    switch (mixedAttempts) {
      case 1:
        res.send(
          JSON.stringify({
            data: {
              valid: false,
            },
          })
        )
        break

      case 2:
        res.status(501)
        res.send(
          JSON.stringify({
            message: 'error',
          })
        )
        break

      case 3:
        res.send(
          JSON.stringify({
            data: {
              valid: false,
            },
          })
        )
        break

      case 4:
        res.status(502)
        res.send(
          JSON.stringify({
            message: 'error',
          })
        )
        break

      default:
        res.send(
          JSON.stringify({
            data: {
              valid: true,
            },
          })
        )
        break
    }

    res.setHeader('Date', '12345')
    if (serverState.retryOnErrorAttempts > 3) {
      res.send(
        JSON.stringify({
          data: {
            valid: true,
          },
        })
      )
    } else {
      res.status(500 + serverState.retryOnErrorAttempts)
      res.send(
        JSON.stringify({
          message: 'error',
        })
      )
    }
  })

  app.get('/api/query/read-model/refresh-token', (req: any, res: any) => {
    const auth = req.header('Authorization')
    res.setHeader('Date', '12345')
    if (auth !== 'Bearer valid-token') {
      res.status(401)
      res.send(
        JSON.stringify({
          message: 'unauthorized access',
        })
      )
    } else {
      res.send(
        JSON.stringify({
          data: {
            authorized: true,
          },
        })
      )
    }
  })

  app.get('/get-token', (req: any, res: any) => {
    serverState.tokenRequests++
    res.send(
      JSON.stringify({
        token: 'valid-token',
      })
    )
  })

  server = app.listen('3300')
})

afterAll(() => {
  server.close()
})

