      currentOra = {
        failed: false,
        start() {
          this.started = true;
          return currentOra;
        },
        succeed() {
          this.succeeded = true;
          return currentOra;
        },
        fail() {
          this.failed = true;
          return currentOra;
        },
        stop() {
          this.failed = true;
          return currentOra;
        },
        get text() {
          return (currentOra! as any)._text;
        },
        set text(newText) {
          (currentOra! as any)._text = newText;
        },
      } as any;
      (currentOra as any).succeeded = false;
      (currentOra as any).failed = false;
      (currentOra as any)._text = text;
      return currentOra;
    };
